import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { BASE_URL, fake, newSession, openProject, type Session } from '../helpers';

// PROTOTYPE of the Python "Run" (Pyodide in a Worker inside an isolated iframe). It only runs if static/pyodide exists
// (generated by `python3 scripts/fetch_pyodide.py`); otherwise it is skipped. Real timings and sizes are printed to the console.
const HAVE = fs.existsSync(path.resolve(import.meta.dir, '../../../static/pyodide/pyodide-lock.json'));

describe.skipIf(!HAVE)('python in the browser (prototype)', () => {
  let s: Session;
  const downloaded: { url: string; bytes: number }[] = [];
  const external: string[] = [];
  const run = (code: string, opts: Record<string, unknown> = {}) => s.page.evaluate(([c, o]) => (window as any).PyRunner.run(c, o), [code, opts] as const) as Promise<any>;
  const pyodideFiles = () => downloaded.filter(b => b.url.includes('/static/pyodide/')).map(b => b.url.split('/').pop()!);

  beforeAll(async () => {
    fake.seedRepo('demo', 'py', { 'main.tex': '\\documentclass{article}\n\\begin{document}Oi\n\\end{document}\n' }, ['neoleaf']);
    s = await newSession();
    s.page.on('request', r => {
      const u = r.url();
      if (!u.startsWith(BASE_URL) && !u.startsWith('data:') && !u.startsWith('blob:') && !u.startsWith('about:')) external.push(u);
    });
    s.page.on('response', async r => {
      const u = r.url();
      if (u.includes('/static/pyodide/')) downloaded.push({ url: u, bytes: Number(r.headers()['content-length'] || 0) });
    });
    await openProject(s.page, 'demo__py');
  });
  afterAll(async () => { await s.context.close(); });

  test('the engine exists and the first run downloads only the base (no numpy)', async () => {
    expect(await s.page.evaluate(() => (window as any).PyRunner.available())).toBe(true);
    const r = await run('print(1 + 1)');
    expect(r.error).toBe('');
    expect(r.ok).toBe(true);
    expect(r.stdout.trim()).toBe('2');
    const files = pyodideFiles();
    expect(files).toContain('pyodide.asm.wasm');
    expect(files).toContain('python_stdlib.zip');
    expect(files.some(a => a.startsWith('numpy'))).toBe(false);
    const mb = downloaded.reduce((t, b) => t + b.bytes, 0) / 1024 / 1024;
    console.log(`BASE: ${files.length} files, ${mb.toFixed(1)} MB uncompressed; engine ready in ${r.initMs} ms, script in ${r.ms} ms`);
  });

  test('the second run is fast and each run starts clean', async () => {
    await run('value = 41');
    const r = await run('print("value" in globals())');
    expect(r.stdout.trim()).toBe('False');
    console.log(`SECOND run: ${r.ms} ms`);
    expect(r.ms).toBeLessThan(5000);
  });

  test('packages are only downloaded when the code imports them (numpy yes, pandas not yet)', async () => {
    const before = pyodideFiles().length;
    const r = await run('import numpy as np\nprint(int(np.arange(5).sum()))');
    expect(r.error).toBe('');
    expect(r.stdout.trim()).toBe('10');
    const added = pyodideFiles().slice(before);
    expect(added.some(a => a.startsWith('numpy'))).toBe(true);
    expect(added.some(a => a.startsWith('pandas'))).toBe(false);
    console.log(`NUMPY: ${added.join(', ')}; ${r.ms} ms`);
  });

  test('reads a project file (CSV) with pandas and produces a figure with matplotlib', async () => {
    const r = await run([
      'import pandas as pd', 'import matplotlib.pyplot as plt',
      'df = pd.read_csv("data.csv")', 'print(df["v"].sum())',
      'df.plot(x="n", y="v")', 'plt.savefig("figures/chart.png", dpi=80)', 'plt.savefig("chart.pdf")',
    ].join('\n'), { files: { 'data.csv': 'n,v\n1,10\n2,20\n3,30\n', 'figures/.keep': '' } });
    expect(r.error).toBe('');
    expect(r.stdout.trim()).toBe('60');
    expect(Object.keys(r.files).sort()).toEqual(['chart.pdf', 'figures/chart.png']);   // only what the script produced
    expect(Array.from(r.files['figures/chart.png'].slice(0, 8)).map((b: number) => b.toString(16).padStart(2, '0')).join('')).toBe('89504e470d0a1a0a');
    expect(String.fromCharCode(...r.files['chart.pdf'].slice(0, 4))).toBe('%PDF');
    console.log(`PANDAS+MATPLOTLIB: ${r.ms} ms; png ${r.files['figures/chart.png'].length} bytes`);
  });

  test('a Python error comes back with the traceback and does not bring the engine down', async () => {
    const r = await run('x = 1\n1 / 0');
    expect(r.ok).toBe(false);
    expect(r.error).toContain('ZeroDivisionError');
    expect((await run('print("ok")')).stdout.trim()).toBe('ok');
  });

  test('isolation: the script reaches neither the NeoLeaf API nor the internet', async () => {
    const before = external.length;   // Monaco and other page libraries come from CDNs; here only what Python tries counts
    const r = await run([
      'import js',
      'for target in ["' + BASE_URL + '/api/user/profile", "https://example.org/", "https://api.crossref.org/works?rows=1"]:',
      '    try:',
      '        resp = await js.fetch(target)',
      '        print("ANSWERED", target, resp.status)',
      '    except Exception as e:',
      '        print("BLOCKED", target)',
      'print("cookie:", repr(getattr(js, "document", None)))',
    ].join('\n'));
    expect(r.error).toBe('');
    expect(r.stdout).not.toContain('ANSWERED');
    expect((r.stdout.match(/BLOCKED/g) || []).length).toBe(3);
    expect(external.slice(before)).toEqual([]);   // Python could not even attempt a request outside NeoLeaf
    expect(await s.page.locator('#py-runner-frame').getAttribute('sandbox')).toBe('allow-scripts');
  });

  test('infinite loop: the timeout interrupts and the engine works again on the next run', async () => {
    const r = await run('while True:\n    pass', { timeoutMs: 3000 });
    expect(r.ok).toBe(false);
    expect(r.error).toContain('Timed out');
    const t0 = Date.now();
    const after = await run('print("voltou")');
    expect(after.stdout.trim()).toBe('voltou');
    console.log(`AFTER the timeout, restarting the engine took ${Date.now() - t0} ms`);
  });

  test('input file names are validated', async () => {
    const r = await s.page.evaluate(async () => { try { await (window as any).PyRunner.run('1', { files: { '../outside.txt': 'x' } }); return 'accepted'; } catch (e: any) { return e.message; } });
    expect(r).toContain('Invalid');
  });
});
